<script>document.addEventListener('DOMContentLoaded',()=>{document.querySelectorAll('[data-tabs]').forEach(tabs=>{const buttons=[...tabs.querySelectorAll('[role="tab"]')],panels=[...tabs.querySelectorAll('[role="tabpanel"]')];buttons.forEach(button=>button.addEventListener('click',()=>{buttons.forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-selected',String(active))});panels.forEach(panel=>{const active=panel.id===button.dataset.tab;panel.classList.toggle('active',active);panel.hidden=!active})}))})});</script>
